import React from 'react';
import { useNavigate } from 'react-router-dom';

const SuccessMessage = ({ formData }) => {
    const navigate = useNavigate();

    const clickHandler = (event) => {
        event.preventDefault();
        navigate('/takequiz');
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gradient-to-r from-teal-300 to-indigo-500 p-6">
            <div className="bg-white shadow-2xl rounded-xl p-8 max-w-lg w-full">
                <h2 className="text-4xl font-bold text-center text-gray-800 mb-6">Quiz Created Successfully!</h2>
                <h4 className="text-xl font-semibold text-gray-600 mb-4 text-center">Quiz Details:</h4>

                <div className="space-y-2 mb-6">
                    <p className="text-gray-700"><strong>Name:</strong> {formData.name}</p>
                    <p className="text-gray-700"><strong>Exam:</strong> {formData.exam}</p>
                    <p className="text-gray-700"><strong>Difficulty Levels:</strong> {formData.difficultyLevels.join(', ')}</p>
                    <p className="text-gray-700"><strong>Class / Year:</strong> {formData.classYear}</p>
                    <p className="text-gray-700"><strong>Subjects:</strong> {formData.subjects.join(', ')}</p>
                    <p className="text-gray-700"><strong>Topics:</strong> {formData.topics.join(', ')}</p>
                    <p className="text-gray-700"><strong>Quiz Mode:</strong> {formData.quizMode}</p>
                    <p className="text-gray-700"><strong>Number of Questions:</strong> {formData.numberOfQuestions}</p>

                    {formData.addHints && <p className="text-gray-700"><strong>Hints:</strong> Enabled</p>}
                    {formData.answerExplanation ?
                        <p className="text-gray-700"><strong>Answer Explanation:</strong> Enabled</p> :
                        <p className="text-gray-700"><strong>Answer Explanation:</strong> Disabled</p>}
                    {formData.breakIntoSubtopics ?
                        <p className="text-gray-700"><strong>Break Into Subtopics:</strong> Enabled</p> :
                        <p className="text-gray-700"><strong>Break Into Subtopics:</strong> Disabled</p>}
                </div>

                <div className="space-y-4">
                    <button
                        className="w-full bg-green-500 text-white py-3 rounded-lg text-lg font-semibold transition transform hover:scale-105 focus:outline-none"
                        onClick={clickHandler}
                    >
                        Start Quiz
                    </button>

                    <button
                        className="w-full bg-blue-500 text-white py-3 rounded-lg text-lg font-semibold transition transform hover:scale-105 focus:outline-none"
                        onClick={() => window.location.reload()}
                    >
                        Create Another Quiz
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SuccessMessage;
